export function translate(dictionary, key, values = {}) {
  const message = key.split(".").reduce((value, part) => value?.[part], dictionary);
  if (typeof message !== "string") return key;
  return message.replace(/\{(\w+)\}/g, (_, name) => values[name] ?? `{${name}}`);
}

